def semver_sort(versions):
    def parse(v):
        main = v.split('+', 1)[0]
        if '-' in main:
            core, pre = main.split('-', 1)
        else:
            core, pre = main, None
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def pre_key(pre_ids):
        if pre_ids is None:
            return None
        key = []
        for ident in pre_ids:
            if ident.isdigit():
                key.append((0, int(ident), ''))
            else:
                key.append((1, 0, ident))
        return key

    def cmp_pre(a, b):
        # a, b are pre_ids lists or None
        if a is None and b is None:
            return 0
        if a is None:
            return 1  # no prerelease > has prerelease
        if b is None:
            return -1
        ka = pre_key(a)
        kb = pre_key(b)
        for x, y in zip(ka, kb):
            if x < y:
                return -1
            if x > y:
                return 1
        if len(ka) < len(kb):
            return -1
        if len(ka) > len(kb):
            return 1
        return 0

    import functools

    def cmp(v1, v2):
        p1 = parse(v1)
        p2 = parse(v2)
        for i in range(3):
            if p1[i] != p2[i]:
                return -1 if p1[i] < p2[i] else 1
        return cmp_pre(p1[3], p2[3])

    return sorted(versions, key=functools.cmp_to_key(cmp))

